// Inlines the two markdown assets into TypeScript so the plugin runs as plain
// TS under Bun: no .md loader, no bundling step for the server half.
import { readFileSync, writeFileSync } from "node:fs";

function lit(file) {
  const md = readFileSync(file, "utf8");
  return md.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

const skill = lit("skills/opencode-agy/SKILL.md");
const command = lit("commands/agy.md");

const out =
  "// Generated by scripts/gen-skill-text.mjs. Do not edit by hand.\n" +
  "export const skillMarkdown = `" +
  skill +
  "`;\n\n" +
  "export const commandMarkdown = `" +
  command +
  "`;\n";

writeFileSync("src/md.generated.ts", out, "utf8");
console.log("written", out.length, "chars");
